'use strict';
const $ = (s, r = document) => r.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid = () => crypto.randomUUID();
const today = () => new Date().toLocaleDateString('en-CA');
const fmtDate = d => { const date = new Date(d + 'T12:00:00'); return Number.isNaN(+date) ? '—' : date.toLocaleDateString('id-ID', {day:'numeric',month:'short',year:'numeric'}); };
const number = v => Number(v).toLocaleString('id-ID');
const kinds = {plant:{label:'Tanaman',color:'#729c43'},check:{label:'Perlu diperiksa',color:'#df9c43'},gap:{label:'Dugaan titik kosong',color:'#cd7664'}};
const paths = {
  leaf:'M20 4C10 3 3 8 5 15s12 7 15-11ZM4 20 14 10', grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',
  folder:'M3 7V5h6l2 2h10v13H3Z', file:'M6 3h8l4 4v14H6ZM14 3v5h4M9 12h6M9 16h6', settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',
  plus:'M12 5v14M5 12h14', upload:'M12 16V3M7 8l5-5 5 5M4 16v5h16v-5', download:'M12 3v13M7 11l5 5 5-5M4 17v4h16v-4',
  image:'M3 3h18v18H3ZM3 16l5-5 5 5 3-3 5 5M15 7h.01', check:'m5 12 4 4L19 6', pin:'M12 22s7-7 7-13A7 7 0 0 0 5 9c0 6 7 13 7 13ZM12 6a3 3 0 1 0 0 6 3 3 0 0 0 0-6Z',
  clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18ZM12 7v5l3 2', arrow:'M5 12h14M14 7l5 5-5 5', chevron:'m9 5 7 7-7 7', minus:'M5 12h14', close:'m6 6 12 12M6 18 18 6',
  undo:'M8 4 3 9l5 5M3 9h11a6 6 0 0 1 0 12', pointer:'m5 3 14 9-7 2-3 7Z', trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7',
  alert:'m12 3 10 18H2ZM12 9v5M12 17h.01', info:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18ZM12 11v6M12 7h.01', layers:'m12 3 10 5-10 5L2 8ZM2 12l10 5 10-5M2 16l10 5 10-5',
  ai:'M12 3v3M12 18v3M3 12h3M18 12h3M6 6l2 2M16 16l2 2M6 18l2-2M16 8l2-2M12 8l4 4-4 4-4-4Z', print:'M6 8V3h12v5M6 17H3V8h18v9h-3M6 13h12v8H6ZM17 10h.01',
  north:'m12 2 7 19-7-5-7 5Z', eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12ZM12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6Z', refresh:'M20 7v5h-5M4 17v-5h5M5 7a8 8 0 0 1 13-2l2 3M4 16l2 3a8 8 0 0 0 13-2'
};
const icon = (name, size = 17, cls='') => `<svg class="${cls}" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name] || paths.leaf}"/></svg>`;
let db, state, view='overview', mode='select', zoom=1, selectedId=null, busy=false, toastTimer, undoStack=[];
let sessionSaved=true;
const activeSurvey = () => state.surveys.find(s=>s.id===state.activeSurveyId) || state.surveys[0];
const activePhoto = () => { const s=activeSurvey(); return s?.photos.find(p=>p.id===state.activePhotoId) || s?.photos[0]; };
const confirmed = p => (p?.annotations || []).filter(a=>a.status!=='pending');
const count = (p,k) => confirmed(p).filter(a=>a.kind===k).length;
const pending = p => (p?.annotations || []).filter(a=>a.status==='pending');
const sampleCoords = () => {const a=[];for(let r=0;r<5;r++)for(let c=0;c<6;c++){if((r===1&&c===3)||(r===3&&c===1))continue;a.push({x:(173+c*159+(r%2?15:0))/1200,y:(135+r*126)/800});}return a;};
function sampleImage(){
  const trees=sampleCoords().map((p,i)=>{const x=p.x*1200,y=p.y*800;return `<g transform="translate(${x},${y})"><ellipse cy="10" rx="38" ry="28" fill="#122e20" opacity=".25"/><circle r="36" fill="${['#53774b','#5d824e','#68894e'][i%3]}"/><path d="M0 30 0-28M-25-17 25 17M-28 4 27-4M-17 25 17-25" stroke="#8da76a" stroke-width="6" opacity=".45"/><circle r="9" fill="#41633e"/></g>`;}).join('');
  const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="800" viewBox="0 0 1200 800"><defs><pattern id="grass" width="25" height="25" patternUnits="userSpaceOnUse"><rect width="25" height="25" fill="#90a376"/><path d="m4 5 3 8m9 5 2-5m-4-10 2 4" stroke="#7a9563" opacity=".35"/></pattern><filter id="shadow"><feDropShadow dx="1" dy="3" stdDeviation="3" flood-opacity=".12"/></filter></defs><rect width="1200" height="800" fill="url(#grass)"/><path d="M80 0v800M1120 0v800M0 755h1200" stroke="#c5c39b" stroke-width="54"/><path d="M80 0v800M1120 0v800M0 755h1200" stroke="#ded5ac" stroke-width="3" stroke-dasharray="9 14" opacity=".6"/><g stroke="#a7b58c" stroke-width="2" opacity=".6">${[198,324,450,576].map(y=>`<path d="M115 ${y}h970"/>`).join('')}</g><path d="M70 75h1040v630H70Z" fill="none" stroke="#e2efba" stroke-width="3" stroke-dasharray="14 10"/><g filter="url(#shadow)">${trees}</g><g fill="#b8af7e"><ellipse cx="665" cy="261" rx="28" ry="20"/><ellipse cx="347" cy="513" rx="28" ry="20"/></g><g transform="translate(954 640)"><path d="m-30 23 30-38 35 34Z" fill="#899578" opacity=".6"/></g><rect x="122" y="25" width="400" height="31" rx="5" fill="#214735" opacity=".85"/><text x="137" y="46" fill="#e2edcf" font-family="sans-serif" font-size="14" letter-spacing="2">ILUSTRASI PARSEL • BUKAN CITRA DRONE</text><text x="122" y="789" fill="#55644b" font-size="13" font-family="sans-serif">WALLACEA / CONTOH PENANDAAN TANAMAN</text></svg>`;
  return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg);
}
function makeDemo(){
  const photoId=uid();const marks=sampleCoords().map((p,i)=>({id:uid(),...p,kind:'plant',note:'Penanda contoh '+(i+1),source:'manual',status:'confirmed'}));
  marks.push({id:uid(),x:665/1200,y:261/800,kind:'gap',note:'Cek langsung: titik tanpa kanopi pada ilustrasi.',source:'manual',status:'confirmed'},{id:uid(),x:347/1200,y:513/800,kind:'gap',note:'Verifikasi keberadaan tanaman di lapangan.',source:'manual',status:'confirmed'},{id:uid(),x:0.819,y:0.642,kind:'check',note:'Contoh lokasi untuk pemeriksaan petugas.',source:'manual',status:'confirmed'});
  const s={id:uid(),name:'Parsel demonstrasi',crop:'Tanaman perkebunan',location:'Lokasi ilustrasi',date:today(),notes:'Data contoh untuk mencoba penandaan. Tidak mewakili hasil penerbangan atau analisis AI.',isDemo:true,createdAt:new Date().toISOString(),photos:[{id:photoId,name:'parsel-contoh.svg',dataUrl:sampleImage(),width:1200,height:800,annotations:marks,createdAt:new Date().toISOString()}]};
  return s;
}
async function init(){
  try{
    db=await new Promise((resolve,reject)=>{const req=indexedDB.open('wallacea-survey',1);req.onupgradeneeded=()=>req.result.createObjectStore('workspace');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});
    state=await new Promise((resolve,reject)=>{const req=db.transaction('workspace').objectStore('workspace').get('state');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});
  }catch(e){sessionSaved=false;}
  if(!state){const demo=makeDemo();state={schemaVersion:1,surveys:[demo],activeSurveyId:demo.id,activePhotoId:demo.photos[0].id,settings:{apiUrl:''}};}
  state.settings ||= {apiUrl:''};render();if(!db)toast('Penyimpanan browser tidak tersedia. Ekspor backup sebelum menutup halaman.');
}
async function persist(){
  if(!db){sessionSaved=false;updateSaveState();return;}
  try{await new Promise((resolve,reject)=>{const tx=db.transaction('workspace','readwrite');tx.objectStore('workspace').put(state,'state');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});sessionSaved=true;}
  catch(e){sessionSaved=false;toast('Penyimpanan gagal atau penuh. Segera ekspor backup JSON.');}updateSaveState();
}
function updateSaveState(){const el=$('#save-state');if(el)el.textContent=sessionSaved?'Tersimpan di browser':'Belum tersimpan · ekspor backup';}
function toast(msg){clearTimeout(toastTimer);$('#toast').textContent=msg;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),5000);}
function shell(content){return `<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">${icon('leaf',24)}</span>WALLACEA</div><div class="brand-sub">FIELD INTELLIGENCE</div><div class="nav-label">WORKSPACE</div><nav class="nav" aria-label="Navigasi utama">${[['overview','grid','Ringkasan'],['surveys','folder','Survei lahan'],['reports','file','Laporan'],['settings','settings','Pengaturan']].map(([v,i,t])=>`<button data-action="nav" data-view="${v}" class="${view===v?'active':''}" ${view===v?'aria-current="page"':''}>${icon(i)}<span>${t}</span></button>`).join('')}</nav><div class="sidebar-note"><div class="eyebrow">DARI FOTO KE TINDAKAN</div><p>Kumpulkan bukti visual.<br>Tinjau bersama petugas.<br>Putuskan dengan lebih jelas.</p><button class="small-link" data-action="guide">Panduan survei ${icon('arrow',13)}</button></div><div class="sidebar-footer"><span class="dot"></span> Versi awal · pasca-penerbangan</div></aside><main class="main"><header class="topbar"><div class="breadcrumb">Workspace ${icon('chevron',11)} <strong>${({overview:'Ringkasan survei',surveys:'Survei lahan',reports:'Laporan',settings:'Pengaturan'})[view]}</strong></div><div class="top-meta"><span>K919 MAX · unggah berkas</span><span id="save-state">${sessionSaved?'Tersimpan di browser':'Belum tersimpan · ekspor backup'}</span><div class="avatar" title="Workspace lokal">WF</div></div></header><div class="content">${content}<footer class="footer"><span>WALLACEA © ${new Date().getFullYear()} · Lihat lebih jelas, rawat lebih tepat.</span><span>Data lokal di perangkat ini · <button class="text-btn" data-action="backup">Ekspor backup</button></span></footer></div></main></div>`;}
function intro(title,subtitle,actions=''){return `<div class="intro"><div><div class="eyebrow">PANTAU. PAHAMI. TINDAK LANJUTI.</div><h1>${title}</h1><p>${subtitle}</p></div><div class="actions">${actions}</div></div>`;}
function demoBanner(){return activeSurvey()?.isDemo?`<div class="info-banner">${icon('info',15)}<span>Mode contoh. Gambar adalah ilustrasi; penanda bukan hasil AI atau survei lapangan.</span><button data-action="new-survey">Mulai survei nyata ${icon('arrow',12)}</button></div>`:'';}
function stat(label,value,foot,i,cls=''){return `<div class="stat"><div class="stat-top"><span>${label}</span><span class="stat-icon">${icon(i,16)}</span></div><div class="stat-value ${cls}">${value}</div><div class="stat-foot">${foot}</div></div>`;}
function render(){
  const main={overview:overview,surveys:surveyView,reports:reportView,settings:settingsView}[view];$('#app').innerHTML=shell(main());bindDrop();
}
function overview(){
  const s=activeSurvey(),p=activePhoto();
  const actions=`<button class="btn" data-action="report">${icon('download',15)} Laporan</button><button class="btn primary" data-action="new-survey">${icon('plus',15)} Survei baru</button>`;
  if(!s)return intro('Mulai dari lahan pertama.','Buat survei lalu unggah foto asli dari drone.',actions)+`<div class="full-card"><div class="empty"><div class="empty-icon">${icon('leaf',32)}</div><h2>Workspace siap digunakan</h2><p>Foto dan catatan akan disimpan di browser ini. Buat backup secara berkala.</p><button class="btn primary" data-action="new-survey">${icon('plus')} Buat survei</button></div></div>`;
  const n=count(p,'plant'),f=count(p,'check')+count(p,'gap');
  return intro('Lihat lahan lebih dekat.','Kelola foto drone, tinjau tanaman, dan catat titik yang perlu diperiksa.',actions)+demoBanner()+`<section class="stats" aria-label="Ringkasan foto aktif">${stat('Foto dalam survei',number(s.photos.length),'Foto asli atau ilustrasi contoh','image')}${stat('Tanaman ditandai',number(n),'Pada foto aktif · sudah ditinjau','leaf')}${stat('Titik pemeriksaan',number(f),'Pada foto aktif · perlu verifikasi','pin','orange')}${stat('Kandidat AI',number(pending(p).length),pending(p).length?'Menunggu tinjauan manusia':'Belum ada kandidat untuk ditinjau','ai')}</section><section class="workspace"><aside class="photo-panel"><div class="panel-title">Foto survei <span class="counter">${s.photos.length}</span></div><div class="photo-list">${s.photos.map((q,i)=>`<button class="photo-card ${q.id===p?.id?'selected':''}" data-action="select-photo" data-id="${q.id}" aria-label="Buka foto ${esc(q.name)}"><img src="${esc(q.dataUrl)}" alt="Pratinjau ${esc(q.name)}"><strong>${String(i+1).padStart(2,'0')} · ${esc(q.name)}</strong><small>${q.width} × ${q.height} px · ${q.annotations.length} penanda</small></button>`).join('')}</div><button class="photo-upload" data-action="upload">${icon('plus',18)} Tambah foto<br><span>JPG, PNG, WebP</span></button><p class="photo-note">Gunakan file asli, bukan tangkapan layar remote. Maksimal 20 MB per foto.</p></aside><div class="image-panel"><div class="image-toolbar"><div class="toolbar-left">${icon('layers',15)}<strong>${esc(p?.name || 'Belum ada foto')}</strong><span class="tag">${s.isDemo?'CONTOH':'FOTO ASLI'}</span></div><div class="tool-group"><button class="icon-btn" aria-label="Perkecil foto" data-action="zoom-out">${icon('minus',14)}</button><span>${Math.round(zoom*100)}%</span><button class="icon-btn" aria-label="Perbesar foto" data-action="zoom-in">${icon('plus',14)}</button><button class="icon-btn" aria-label="Sesuaikan foto" data-action="zoom-reset">${icon('refresh',14)}</button></div></div>${p?photoCanvas(p):`<div class="viewport" id="drop-zone"><div class="empty"><div class="empty-icon">${icon('upload',28)}</div><h2>Foto pertama, langkah pertama.</h2><p>Unggah foto dari kartu memori drone. Geser berkas ke area ini atau pilih dari perangkat.</p><button class="btn primary" data-action="upload">${icon('upload',15)} Pilih foto</button></div></div>`}<div class="image-caption"><span>${p?`${p.width} × ${p.height} px · ${s.isDemo?'Ilustrasi':'Koordinat gambar'}`:'Berkas tetap berada di browser hingga Anda memakai backend AI.'}</span><span>Bukan peta georeferensi</span></div><div class="annotation-tools" aria-label="Alat penandaan"><button class="tool ${mode==='select'?'active':''}" data-action="mode" data-mode="select">${icon('pointer',13)} Pilih</button>${Object.entries(kinds).map(([k,v])=>`<button class="tool ${mode===k?'active':''}" data-action="mode" data-mode="${k}"><i style="--c:${v.color}"></i>${k==='plant'?'Tanaman':k==='check'?'Periksa':'Titik kosong'}</button>`).join('')}<button class="tool undo" data-action="undo" ${undoStack.length?'':'disabled'} aria-label="Urungkan penandaan">${icon('undo',13)}</button></div></div>${findings(p)}</section><section class="bottom-grid"><div class="bottom-card"><div class="section-head"><h2>Alur survei Anda</h2><button class="text-btn" data-action="guide">Lihat panduan ${icon('arrow',12)}</button></div><div class="workflow"><div class="step done"><span>${icon('check',12)}</span>Buat survei</div><div class="step-line"></div><div class="step ${p?'done':'active'}"><span>${p?icon('check',12):'2'}</span>Unggah</div><div class="step-line"></div><div class="step ${p?'active':''}"><span>3</span>Tinjau foto</div><div class="step-line"></div><div class="step"><span>4</span>Laporan</div></div></div><div class="bottom-card"><div class="section-head"><h2>${esc(s.name)}</h2><button class="text-btn" data-action="edit-survey">Edit ${icon('chevron',11)}</button></div><div class="survey-detail"><div class="detail"><small>JENIS TANAMAN</small><strong>${esc(s.crop)}</strong></div><div class="detail"><small>TANGGAL SURVEI</small><strong>${fmtDate(s.date)}</strong></div><div class="detail"><small>LOKASI</small><strong>${esc(s.location || 'Belum diisi')}</strong></div><div class="detail"><small>SUMBER DATA</small><strong>${s.isDemo?'Ilustrasi contoh':'Unggah foto · pasca-terbang'}</strong></div></div></div></section>`;
}
function photoCanvas(p){return `<div class="viewport" id="drop-zone"><div class="image-wrap ${mode==='select'?'':'marking'}" id="image-wrap" style="width:${zoom*100}%"><img src="${esc(p.dataUrl)}" id="main-photo" alt="${esc(p.name)}" draggable="false"><svg class="image-overlay" id="annotation-overlay" viewBox="0 0 ${p.width} ${p.height}" aria-label="Penanda pada foto">${p.annotations.map((a,i)=>{const r=Math.max(p.width,p.height)/85;return `${a.box?`<rect class="bbox" x="${a.box[0]*p.width}" y="${a.box[1]*p.height}" width="${a.box[2]*p.width}" height="${a.box[3]*p.height}"/>`:''}<g class="point ${a.id===selectedId?'selected':''}" data-marker="${a.id}" tabindex="0" role="button" aria-label="Penanda ${i+1}: ${kinds[a.kind].label}${a.status==='pending'?', belum ditinjau':''}"><title>${esc(kinds[a.kind].label)} · ${esc(a.note || '')}</title><circle cx="${a.x*p.width}" cy="${a.y*p.height}" r="${r}" fill="${a.status==='pending'?'#5b8aa1':kinds[a.kind].color}" stroke="#f2f7e1" stroke-width="${r*.18}" ${a.status==='pending'?`stroke-dasharray="${r*.4} ${r*.2}"`:''}/><text class="marker-num" x="${a.x*p.width}" y="${a.y*p.height}" style="font-size:${r}px">${i+1}</text></g>`;}).join('')}</svg></div></div>`;}
function findings(p){
  const anns=p?.annotations || [];const items=anns.filter(a=>a.kind!=='plant'||a.status==='pending'||a.id===selectedId);const selected=anns.find(a=>a.id===selectedId);
  return `<aside class="findings-panel"><div class="panel-title">Tinjauan foto <span class="counter">${items.length}</span></div><p class="findings-heading">Pilih penanda untuk menulis catatan atau mengoreksi hasil.</p><div class="finding-list">${items.length?items.map(a=>`<button class="finding ${a.id===selectedId?'active':''}" data-action="select-marker" data-id="${a.id}"><span class="finding-icon" ${a.status==='pending'?'style="color:#5d8ea6;background:#eef3f5"':''}>${icon(a.status==='pending'?'ai':a.kind==='plant'?'leaf':'pin',14)}</span><span><strong>${esc(kinds[a.kind].label)}</strong><small>${a.status==='pending'?`Kandidat AI · ${Math.round((a.confidence || 0)*100)}% · belum ditinjau`:esc(a.note || 'Belum ada catatan')}</small></span><span class="finding-id">${String(anns.indexOf(a)+1).padStart(2,'0')}</span></button>`).join(''):`<div class="photo-note" style="display:block;margin:4px 0 30px">${p?'Belum ada temuan. Pilih alat penandaan, lalu klik lokasi pada foto.':'Unggah foto untuk memulai peninjauan.'}</div>`}</div>${selected?`<div class="selected-note"><label for="marker-kind">Jenis penanda #${anns.indexOf(selected)+1}</label><select id="marker-kind" style="width:100%;padding:7px;border:1px solid #dce4d3;border-radius:5px;margin-bottom:10px;color:#48643e;font-size:11px">${Object.entries(kinds).map(([k,v])=>`<option value="${k}" ${selected.kind===k?'selected':''}>${v.label}</option>`).join('')}</select><label for="marker-note">Catatan pemeriksaan</label><textarea id="marker-note" maxlength="1000" placeholder="Apa yang perlu dicek di lokasi ini?">${esc(selected.note)}</textarea><div class="actions"><button class="btn lime" data-action="save-marker">${icon('check',12)} ${selected.status==='pending'?'Terima & simpan':'Simpan'}</button><button class="btn danger" data-action="delete-marker">${icon('trash',12)} ${selected.status==='pending'?'Tolak':'Hapus'}</button></div></div>`:''}<div class="ai-card"><div class="ai-card-top"><span>${icon('ai',13)} ASISTEN DETEKSI</span><span class="tag">${state.settings.apiUrl?'Endpoint diatur':'Belum terhubung'}</span></div><p>${state.settings.apiUrl?'Kirim foto aktif ke backend yang Anda atur. Kandidat harus ditinjau sebelum masuk hitungan.':'Penandaan manual sudah aktif. Deteksi otomatis memerlukan backend dan model tanaman terlatih.'}</p><button class="btn ${state.settings.apiUrl?'primary':''}" data-action="${state.settings.apiUrl?'run-ai':'ai-settings'}" ${state.settings.apiUrl&&(!p||activeSurvey()?.isDemo)?'disabled':''}>${icon('ai',13)} ${state.settings.apiUrl?'Jalankan deteksi':'Siapkan backend AI'}</button><button class="small-link" data-action="import-detections" ${!p?'disabled':''}>Impor hasil deteksi JSON</button></div></aside>`;
}
function surveyView(){return intro('Setiap lahan, satu catatan.','Pisahkan survei berdasarkan lokasi, tanaman, dan tanggal pengambilan gambar.',`<button class="btn" data-action="restore">${icon('upload',15)} Impor backup</button><button class="btn primary" data-action="new-survey">${icon('plus',15)} Survei baru</button>`)+`<div class="survey-grid">${state.surveys.map(s=>`<article class="survey-item">${s.photos[0]?`<img src="${esc(s.photos[0].dataUrl)}" alt="Foto survei ${esc(s.name)}">`:`<div style="height:140px;background:#e9efdf;display:grid;place-items:center;color:#89a56f">${icon('image',36)}</div>`}<div class="survey-item-body"><span class="tag">${s.isDemo?'CONTOH':'SURVEI NYATA'}</span><h2 style="margin-top:10px">${esc(s.name)}</h2><p>${esc(s.crop)} · ${fmtDate(s.date)}<br>${esc(s.location || 'Lokasi belum diisi')} · ${s.photos.length} foto</p><div class="actions"><button class="btn primary" data-action="open-survey" data-id="${s.id}">Buka survei ${icon('arrow',12)}</button><button class="icon-btn" data-action="delete-survey" data-id="${s.id}" aria-label="Hapus survei ${esc(s.name)}">${icon('trash',14)}</button></div></div></article>`).join('') || `<div class="empty"><h2>Belum ada survei</h2><p>Buat survei pertama untuk mengelola foto drone.</p></div>`}</div>`;}
function reportView(){
  const s=activeSurvey();if(!s)return intro('Laporan survei','Buat survei dan unggah foto terlebih dahulu.')+`<div class="full-card"><div class="empty"><h2>Belum ada laporan</h2><button class="btn primary" data-action="new-survey">Buat survei</button></div></div>`;
  return intro('Temuan yang bisa ditindaklanjuti.','Hitungan disajikan per foto. Penanda pada foto yang bertumpang tindih belum dideduplikasi.',`<button class="btn" data-action="csv">${icon('download',15)} Ekspor CSV</button><button class="btn" data-action="png" ${activePhoto()?'':'disabled'}>${icon('image',15)} Foto beranotasi</button><button class="btn primary" data-action="print">${icon('print',15)} Cetak / PDF</button>`)+demoBanner()+`<article class="full-card"><div class="report-hero"><div><div class="eyebrow">WALLACEA · LAPORAN TINJAUAN VISUAL</div><h2>${esc(s.name)}</h2><p>${esc(s.crop)} · ${esc(s.location || 'Lokasi belum diisi')}<br>Tanggal survei: ${fmtDate(s.date)} · ${s.isDemo?'DATA CONTOH':'Unggah berkas drone'}</p></div><div class="brand-mark">${icon('leaf',27)}</div></div><div class="report-summary"><div><strong>${s.photos.length}</strong><small>Foto dalam survei</small></div><div><strong>${s.photos.reduce((a,p)=>a+pending(p).length,0)}</strong><small>Kandidat AI belum ditinjau</small></div><div><strong>Visual</strong><small>Metode pemeriksaan</small></div></div><table class="report-table"><thead><tr><th>FOTO</th><th>TANAMAN</th><th>PERIKSA</th><th>TITIK KOSONG</th><th>KANDIDAT AI</th></tr></thead><tbody>${s.photos.map(p=>`<tr><td>${esc(p.name)}</td><td>${count(p,'plant')}</td><td>${count(p,'check')}</td><td>${count(p,'gap')}</td><td>${pending(p).length}</td></tr>`).join('') || '<tr><td colspan="5">Belum ada foto.</td></tr>'}</tbody></table><h3 style="font-size:13px;margin-top:26px">Catatan pemeriksaan</h3><table class="report-table"><thead><tr><th>FOTO / PENANDA</th><th>JENIS</th><th>CATATAN</th><th>STATUS</th></tr></thead><tbody>${s.photos.flatMap(p=>p.annotations.map((a,i)=>({p,a,i}))).filter(({a})=>a.kind!=='plant'||a.note||a.status==='pending').map(({p,a,i})=>`<tr><td>${esc(p.name)} / #${i+1}</td><td>${esc(kinds[a.kind].label)}</td><td>${esc(a.note || '—')}</td><td>${a.status==='pending'?'Belum ditinjau':a.source==='ai'?'AI · ditinjau':'Manual'}</td></tr>`).join('')||'<tr><td colspan="4">Belum ada catatan pemeriksaan.</td></tr>'}</tbody></table><div class="notice">${s.isDemo?'Laporan ini berisi ilustrasi dan penanda contoh. ':''}Posisi penanda menggunakan koordinat relatif dalam gambar, bukan GPS. Titik kosong dan perubahan visual memerlukan pemeriksaan lapangan; bukan diagnosis penyakit. Hitungan antar foto tidak boleh dijumlahkan sebagai jumlah unik tanaman tanpa deduplikasi.</div>${s.notes?`<p style="font-size:12px;margin-top:20px;line-height:1.8;color:#6e8062"><strong>Catatan survei:</strong> ${esc(s.notes)}</p>`:''}</article>`;
}
function settingsView(){return intro('Sederhana dulu. Siap berkembang.','Atur pemrosesan AI dan kelola data survei di perangkat ini.')+`<section class="instruction-grid"><div class="full-card"><h2>${icon('ai',18)} Hubungkan backend AI</h2><p>Backend Python disediakan terpisah dalam source code. Jalankan dengan model deteksi tanaman yang sudah dilatih. Tidak ada model aktif atau koneksi langsung ke drone pada versi awal.</p><form id="api-form" style="margin-top:20px"><div class="field"><label for="api-url">URL lengkap endpoint analisis</label><input id="api-url" type="url" value="${esc(state.settings.apiUrl)}" placeholder="http://127.0.0.1:8000/analyze"><small>Untuk aplikasi yang dibuka melalui HTTPS, gunakan backend HTTPS. Backend lokal sebaiknya digunakan bersama frontend yang dijalankan lokal. Foto akan dikirim ke URL ini saat Anda menekan deteksi.</small></div><div class="actions"><button class="btn primary" type="submit">Simpan endpoint</button><button class="btn" type="button" data-action="clear-api">Putuskan endpoint</button></div><p class="error" id="api-error"></p></form><div class="notice">Mengatur URL tidak membuktikan model siap. Backend mengembalikan kesalahan yang jelas jika model belum tersedia.</div></div><div class="full-card"><h2>${icon('folder',18)} Data milik Anda</h2><p>Foto dan penanda tersimpan di IndexedDB browser ini, bukan database bersama. Menghapus data browser dapat menghapus workspace. Backup memuat foto: simpan dan bagikan dengan hati-hati.</p><div class="actions" style="margin-top:20px"><button class="btn primary" data-action="backup">${icon('download',15)} Backup JSON</button><button class="btn" data-action="restore">${icon('upload',15)} Pulihkan backup</button></div><div class="notice">Impor menambahkan survei sebagai salinan dengan ID baru. Data yang sudah ada tidak ditimpa. Maksimal 100 MB per backup.</div></div><div class="full-card"><h2>${icon('layers',18)} Format hasil deteksi</h2><p>Impor JSON berlaku untuk foto aktif. Posisi dan ukuran menggunakan nilai 0–1 terhadap gambar. Semua kandidat masuk dengan status belum ditinjau.</p><pre>{
  "image_width": 1920,
  "image_height": 1080,
  "model": "nama-model-anda",
  "detections": [{
    "label": "plant",
    "confidence": 0.86,
    "bbox": [0.10, 0.20, 0.08, 0.12]
  }]
}</pre><p>bbox: [kiri, atas, lebar, tinggi]. Label yang diterima: plant, check, gap. Ukuran gambar harus cocok dengan foto aktif.</p></div><div class="full-card"><h2>${icon('info',18)} Batas versi pertama</h2><p>• Bekerja dari foto setelah drone mendarat.<br>• Tidak mengontrol penerbangan K919 MAX.<br>• Tidak membuat orthomosaic atau menghitung luas lahan.<br>• Tidak mengekstrak atau mengarang posisi GPS.<br>• Tidak menjumlahkan tanaman unik antar foto.<br>• Tidak mendiagnosis hama, penyakit, atau kebutuhan pupuk.</p><div class="actions" style="margin-top:18px"><button class="btn" data-action="guide">Buka panduan survei</button></div></div></section>`;}
function showDialog(html){$('#dialog').innerHTML=html;$('#dialog').showModal();}
function surveyForm(edit=false){
  const s=edit?activeSurvey():null;
  showDialog(`<form id="survey-form" data-edit="${edit?'yes':'no'}"><div class="dialog-top"><h2>${edit?'Edit survei':'Survei lahan baru'}</h2><button class="icon-btn" type="button" data-action="close-dialog" aria-label="Tutup">${icon('close',15)}</button></div><p>Satu survei untuk satu lokasi dan tanggal pengambilan foto.</p><div class="field"><label for="survey-name">Nama survei</label><input id="survey-name" name="name" required maxlength="100" placeholder="Contoh: Kebun Pak Budi · Petak A" value="${esc(s?.name||'')}"></div><div class="field-row"><div class="field"><label for="survey-crop">Jenis tanaman</label><input id="survey-crop" name="crop" required maxlength="80" placeholder="Contoh: jagung" value="${esc(s?.crop||'')}"></div><div class="field"><label for="survey-date">Tanggal survei</label><input id="survey-date" name="date" type="date" required value="${esc(s?.date||today())}"></div></div><div class="field"><label for="survey-location">Lokasi / nama petak</label><input id="survey-location" name="location" maxlength="150" placeholder="Desa, kebun, atau kode petak" value="${esc(s?.location||'')}"><small>Nama lokasi tidak digunakan sebagai koordinat GPS.</small></div><div class="field"><label for="survey-notes">Catatan survei</label><textarea id="survey-notes" name="notes" maxlength="2000" rows="2" placeholder="Kondisi cuaca atau tujuan survei">${esc(s?.notes||'')}</textarea></div><p class="error" id="survey-error"></p><div class="dialog-actions"><button class="btn" type="button" data-action="close-dialog">Batal</button><button class="btn primary" type="submit">${edit?'Simpan perubahan':'Buat survei'}</button></div></form>`);
}
function guide(){showDialog(`<div class="dialog-top"><h2>Dari penerbangan ke laporan.</h2><button class="icon-btn" data-action="close-dialog" aria-label="Tutup">${icon('close',15)}</button></div><p style="margin-top:15px;line-height:2">1. Rekam foto asli menggunakan remote dan prosedur K919 Anda.<br>2. Setelah mendarat, salin berkas ke perangkat ini.<br>3. Buat survei nyata dengan nama lahan dan jenis tanaman.<br>4. Unggah foto JPG, PNG, atau WebP yang cukup tajam.<br>5. Pilih Tanaman, Periksa, atau Titik kosong, lalu klik pada foto.<br>6. Tulis catatan dan verifikasi temuan bersama petugas.<br>7. Ekspor CSV, foto beranotasi, PDF, dan backup JSON.</p><div class="notice">Mulai dari satu foto satu petak. Hasil pada foto bertumpang tindih dapat menghitung tanaman yang sama dua kali. AI baru berjalan jika backend dan model tanaman sudah disiapkan.</div><div class="dialog-actions"><button class="btn primary" data-action="close-dialog">Mengerti</button></div>`);}
function confirmDialog(title,message,fn){showDialog(`<div class="dialog-top"><h2>${esc(title)}</h2></div><p style="margin-top:15px">${esc(message)}</p><div class="dialog-actions"><button class="btn" data-action="close-dialog">Batal</button><button class="btn primary" id="confirm-action">Ya, hapus</button></div>`);$('#confirm-action').onclick=async()=>{$('#dialog').close();await fn();};}
function snapshot(){const p=activePhoto();if(!p)return;undoStack.push({photoId:p.id,annotations:structuredClone(p.annotations)});if(undoStack.length>40)undoStack.shift();}
async function uploadFiles(files){
  const s=activeSurvey();if(!s){surveyForm();return;}
  if(s.isDemo){toast('Buat survei nyata dahulu agar foto asli tidak bercampur dengan contoh.');surveyForm();return;}
  const list=Array.from(files);if(!list.length)return;if(s.photos.length+list.length>40){toast('Maksimal 40 foto per survei. Buat survei baru untuk kelompok berikutnya.');return;}
  setBusy('Menyiapkan foto…');let added=0;const rejected=[];
  for(const file of list){
    try{
      if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('format tidak didukung');
      if(file.size>20*1024*1024)throw Error('lebih dari 20 MB');
      const url=await readAsDataURL(file);const dims=await imageSize(url);
      if(dims.width*dims.height>60_000_000)throw Error('lebih dari 60 megapiksel');
      const p={id:uid(),name:file.name.slice(0,200),dataUrl:url,...dims,annotations:[],createdAt:new Date().toISOString()};s.photos.push(p);state.activePhotoId=p.id;added++;
    }catch(e){rejected.push(file.name+': '+e.message);}
  }
  selectedId=null;zoom=1;undoStack=[];await persist();setBusy(null);view='overview';render();
  toast(`${added} foto ditambahkan.${rejected.length?' '+rejected.length+' berkas ditolak: '+rejected.slice(0,2).join('; '):''}`);
}
function readAsDataURL(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('berkas tidak terbaca'));r.readAsDataURL(file);});}
function imageSize(url){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve({width:img.naturalWidth,height:img.naturalHeight});img.onerror=()=>reject(Error('gambar rusak'));img.src=url;});}
function setBusy(text){busy=!!text;$('.busy')?.remove();if(text){const overlay=document.createElement('div');overlay.className='busy';overlay.setAttribute('role','status');overlay.innerHTML=`<div>${icon('refresh',21,'spin')}<span>${esc(text)}</span></div>`;document.body.append(overlay);}}
function downloadBlob(blob,name){const a=document.createElement('a');const url=URL.createObjectURL(blob);a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const slug = s => String(s).normalize('NFKD').replace(/[^a-zA-Z0-9-]+/g,'-').slice(0,70)||'survei';
function exportBackup(){downloadBlob(new Blob([JSON.stringify({schemaVersion:1,exportedAt:new Date().toISOString(),surveys:state.surveys},null,2)],{type:'application/json'}),`wallacea-backup-${today()}.json`);toast('Backup diunduh. Simpan bersama foto survei Anda.');}
function csvCell(v){let s=String(v??'');if(/^[\s]*[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}
function exportCSV(){
  const s=activeSurvey();if(!s)return;const rows=[['survei','tanggal','tanaman','lokasi','data_contoh','foto','penanda','jenis','status','sumber','x_relatif','y_relatif','keyakinan_model','catatan']];
  for(const p of s.photos)for(const [i,a]of p.annotations.entries())rows.push([s.name,s.date,s.crop,s.location,s.isDemo?'ya':'tidak',p.name,i+1,kinds[a.kind].label,a.status,a.source,a.x.toFixed(6),a.y.toFixed(6),a.confidence??'',a.note]);
  downloadBlob(new Blob(['\uFEFF'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),`wallacea-${slug(s.name)}-penanda.csv`);toast('CSV penanda diunduh. Posisi adalah koordinat gambar, bukan GPS.');
}
async function exportPNG(){
  const p=activePhoto(),s=activeSurvey();if(!p)return;setBusy('Membuat foto beranotasi…');
  try{const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject;img.src=p.dataUrl;});const scale=Math.min(1,4096/Math.max(p.width,p.height));const canvas=document.createElement('canvas');canvas.width=Math.round(p.width*scale);canvas.height=Math.round(p.height*scale);const ctx=canvas.getContext('2d');ctx.drawImage(img,0,0,canvas.width,canvas.height);const r=Math.max(10,canvas.width/85);for(const [i,a]of p.annotations.entries()){const x=a.x*canvas.width,y=a.y*canvas.height;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fillStyle=a.status==='pending'?'#5b8aa1':kinds[a.kind].color;ctx.fill();ctx.strokeStyle='white';ctx.lineWidth=2;ctx.stroke();ctx.fillStyle='white';ctx.textAlign='center';ctx.textBaseline='middle';ctx.font=`bold ${r}px sans-serif`;ctx.fillText(String(i+1),x,y);}const bar=Math.max(38,canvas.width*.032);ctx.fillStyle='#173b32e8';ctx.fillRect(0,canvas.height-bar,canvas.width,bar);ctx.fillStyle='white';ctx.textAlign='left';ctx.font=`${Math.max(11,bar*.35)}px sans-serif`;ctx.fillText(`WALLACEA | ${s.isDemo?'CONTOH ILUSTRASI':'TINJAUAN VISUAL'} | ${count(p,'plant')} tanaman ditandai | bukan posisi GPS`,12,canvas.height-bar/2);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error();downloadBlob(blob,`wallacea-${slug(p.name)}-anotasi.png`);toast('Foto beranotasi diunduh.');}catch(e){toast('Foto tidak dapat diekspor. Coba foto yang lebih kecil.');}finally{setBusy(null);}
}
function validateDetection(data,p){
  if(!data||!Array.isArray(data.detections))throw Error('JSON harus memiliki array detections.');
  if(data.image_width!==p.width||data.image_height!==p.height)throw Error('Ukuran gambar pada JSON tidak cocok dengan foto aktif.');
  if(data.detections.length>3000)throw Error('Maksimal 3.000 kandidat per impor.');
  return data.detections.map(d=>{
    if(!Object.hasOwn(kinds,d.label))throw Error('Label harus plant, check, atau gap.');
    if(!Array.isArray(d.bbox)||d.bbox.length!==4||d.bbox.some(v=>typeof v!=='number'||!Number.isFinite(v)))throw Error('bbox harus berisi empat angka.');
    const [x,y,w,h]=d.bbox;if(x<0||y<0||w<=0||h<=0||x+w>1.00001||y+h>1.00001)throw Error('bbox harus berada dalam gambar, dengan nilai 0–1.');
    if(typeof d.confidence!=='number'||!Number.isFinite(d.confidence)||d.confidence<0||d.confidence>1)throw Error('confidence harus bernilai 0–1.');
    return {id:uid(),kind:d.label,x:Math.min(1,x+w/2),y:Math.min(1,y+h/2),box:[x,y,w,h],confidence:d.confidence,status:'pending',source:'ai',note:'Model: '+String(data.model||'impor').slice(0,100)};
  });
}
async function addDetections(data,targetId){const p=activePhoto();if(!p||p.id!==targetId)throw Error('Foto aktif berubah. Ulangi impor.');const candidates=validateDetection(data,p);if(p.annotations.length+candidates.length>3000)throw Error('Maksimal 3.000 penanda pada satu foto.');snapshot();p.annotations.push(...candidates);selectedId=candidates[0]?.id||null;await persist();render();toast(`${candidates.length} kandidat ditambahkan. Tinjau sebelum masuk hitungan.`);}
async function runAI(){
  const p=activePhoto();if(!p||!state.settings.apiUrl||activeSurvey()?.isDemo)return;
  if(pending(p).length){toast('Tinjau kandidat yang sudah ada sebelum menjalankan deteksi lagi.');return;}
  const target=p.id;setBusy('Mengirim foto ke backend dan menjalankan model…');
  try{const form=new FormData();const image=await(await fetch(p.dataUrl)).blob();form.append('file',image,p.name);const res=await fetch(state.settings.apiUrl,{method:'POST',body:form,signal:AbortSignal.timeout(90000)});const data=await res.json().catch(()=>({detail:'Respons backend bukan JSON.'}));if(!res.ok)throw Error(typeof data.detail==='string'?data.detail:'Backend menolak permintaan.');await addDetections(data,target);}catch(e){toast(e.name==='TimeoutError'?'Backend melewati batas waktu 90 detik.':e instanceof TypeError?'Backend tidak dapat dijangkau. Periksa URL, HTTPS, dan izin CORS.':e.message);}finally{setBusy(null);}
}
async function restoreBackup(file){
  if(!file)return;if(file.size>100*1024*1024){toast('Backup melebihi batas 100 MB.');return;}setBusy('Memeriksa backup…');
  try{const data=JSON.parse(await file.text());if(data.schemaVersion!==1||!Array.isArray(data.surveys)||data.surveys.length>100)throw Error('Format backup WALLACEA tidak sesuai.');const copies=[];
    for(const s of data.surveys){if(typeof s.name!=='string'||!Array.isArray(s.photos)||s.photos.length>40)throw Error('Data survei tidak valid.');const copy={id:uid(),name:s.name.slice(0,100)+' (salinan)',crop:String(s.crop||'').slice(0,80),date:/^\d{4}-\d{2}-\d{2}$/.test(s.date)?s.date:today(),location:String(s.location||'').slice(0,150),notes:String(s.notes||'').slice(0,2000),isDemo:s.isDemo===true,photos:[],createdAt:new Date().toISOString()};
      for(const p of s.photos){if(!p||typeof p.dataUrl!=='string'||!Array.isArray(p.annotations)||p.annotations.length>3000)throw Error('Data foto tidak valid.');let dataUrl=p.dataUrl;if(copy.isDemo)dataUrl=sampleImage();else if(!/^data:image\/(jpeg|png|webp);base64,/.test(dataUrl))throw Error('Format gambar backup tidak didukung.');const dims=await imageSize(dataUrl);if(dims.width*dims.height>60_000_000)throw Error('Foto backup terlalu besar.');const annotations=p.annotations.map(a=>{if(!Object.hasOwn(kinds,a.kind)||!Number.isFinite(a.x)||!Number.isFinite(a.y)||a.x<0||a.x>1||a.y<0||a.y>1)throw Error('Koordinat penanda tidak valid.');return {id:uid(),x:a.x,y:a.y,kind:a.kind,note:String(a.note||'').slice(0,1000),source:a.source==='ai'?'ai':'manual',status:a.status==='pending'?'pending':'confirmed',...(Number.isFinite(a.confidence)&&a.confidence>=0&&a.confidence<=1?{confidence:a.confidence}:{})};});copy.photos.push({id:uid(),name:String(p.name||'foto').slice(0,200),dataUrl,...dims,annotations,createdAt:new Date().toISOString()});}copies.push(copy);}
    state.surveys.push(...copies);state.activeSurveyId=copies[0]?.id||state.activeSurveyId;state.activePhotoId=copies[0]?.photos[0]?.id||null;selectedId=null;undoStack=[];await persist();view='surveys';render();toast(`${copies.length} survei dipulihkan sebagai salinan.`);
  }catch(e){toast('Impor gagal: '+e.message);}finally{setBusy(null);}
}
function bindDrop(){const zone=$('#drop-zone');if(!zone)return;zone.ondragover=e=>{e.preventDefault();zone.classList.add('dragover');};zone.ondragleave=()=>zone.classList.remove('dragover');zone.ondrop=e=>{e.preventDefault();zone.classList.remove('dragover');uploadFiles(e.dataTransfer.files);};}
document.addEventListener('click',async e=>{
  const point=e.target.closest('[data-marker]');if(point){selectedId=point.dataset.marker;render();return;}
  if(e.target.closest('#annotation-overlay')&&!e.target.closest('[data-marker]')){const p=activePhoto();if(!p)return;if(mode==='select'){selectedId=null;render();return;}if(p.annotations.length>=3000){toast('Maksimal 3.000 penanda per foto.');return;}const rect=$('#annotation-overlay').getBoundingClientRect();snapshot();const a={id:uid(),kind:mode,x:Math.max(0,Math.min(1,(e.clientX-rect.left)/rect.width)),y:Math.max(0,Math.min(1,(e.clientY-rect.top)/rect.height)),note:'',source:'manual',status:'confirmed'};p.annotations.push(a);selectedId=a.id;await persist();render();return;}
  const b=e.target.closest('[data-action]');if(!b||b.disabled||busy)return;const action=b.dataset.action;
  if(action==='nav'){view=b.dataset.view;render();}
  else if(action==='new-survey')surveyForm();
  else if(action==='edit-survey')surveyForm(true);
  else if(action==='close-dialog')$('#dialog').close();
  else if(action==='guide')guide();
  else if(action==='upload')$('#photo-input').click();
  else if(action==='select-photo'){state.activePhotoId=b.dataset.id;selectedId=null;zoom=1;undoStack=[];render();await persist();}
  else if(action==='open-survey'){state.activeSurveyId=b.dataset.id;state.activePhotoId=activeSurvey().photos[0]?.id||null;view='overview';selectedId=null;zoom=1;undoStack=[];render();await persist();}
  else if(action==='mode'){mode=b.dataset.mode;render();if(mode!=='select')toast('Klik lokasi pada foto untuk menambahkan penanda '+kinds[mode].label.toLowerCase()+'.');}
  else if(action==='zoom-in'){zoom=Math.min(3,zoom+.25);render();}
  else if(action==='zoom-out'){zoom=Math.max(.5,zoom-.25);render();}
  else if(action==='zoom-reset'){zoom=1;render();}
  else if(action==='select-marker'){selectedId=b.dataset.id;render();}
  else if(action==='save-marker'){const p=activePhoto(),a=p?.annotations.find(a=>a.id===selectedId);if(a){snapshot();a.note=$('#marker-note').value.trim();a.kind=$('#marker-kind').value;a.status='confirmed';await persist();render();toast('Penanda disimpan dan sudah ditinjau.');}}
  else if(action==='delete-marker'){const p=activePhoto();if(p){snapshot();p.annotations=p.annotations.filter(a=>a.id!==selectedId);selectedId=null;await persist();render();toast('Penanda dihapus. Anda bisa mengurungkan tindakan.');}}
  else if(action==='undo'){const prev=undoStack.pop();const p=activePhoto();if(prev&&p?.id===prev.photoId){p.annotations=prev.annotations;selectedId=null;await persist();render();}}
  else if(action==='backup')exportBackup();
  else if(action==='restore')$('#backup-input').click();
  else if(action==='report'){view='reports';render();}
  else if(action==='csv')exportCSV();
  else if(action==='png')await exportPNG();
  else if(action==='print')window.print();
  else if(action==='ai-settings'){view='settings';render();}
  else if(action==='clear-api'){state.settings.apiUrl='';await persist();render();toast('Endpoint AI dilepas.');}
  else if(action==='run-ai')await runAI();
  else if(action==='import-detections')$('#detection-input').click();
  else if(action==='delete-survey'){const s=state.surveys.find(s=>s.id===b.dataset.id);if(s)confirmDialog('Hapus survei?',`Semua foto dan penanda dalam “${s.name}” akan dihapus dari browser ini. Ekspor backup jika diperlukan.`,async()=>{state.surveys=state.surveys.filter(q=>q.id!==s.id);if(state.activeSurveyId===s.id){state.activeSurveyId=state.surveys[0]?.id;state.activePhotoId=state.surveys[0]?.photos[0]?.id;}await persist();render();toast('Survei dihapus dari workspace.');});}
});
document.addEventListener('submit',async e=>{
  if(e.target.id==='survey-form'){e.preventDefault();const form=e.target;const f=new FormData(form);const vals={name:f.get('name').trim(),crop:f.get('crop').trim(),date:f.get('date'),location:f.get('location').trim(),notes:f.get('notes').trim()};if(!vals.name||!vals.crop){$('#survey-error').textContent='Nama survei dan jenis tanaman wajib diisi.';return;}if(form.dataset.edit==='yes')Object.assign(activeSurvey(),vals);else{const s={id:uid(),...vals,isDemo:false,photos:[],createdAt:new Date().toISOString()};state.surveys.push(s);state.activeSurveyId=s.id;state.activePhotoId=null;selectedId=null;undoStack=[];}$('#dialog').close();view='overview';await persist();render();toast(form.dataset.edit==='yes'?'Survei diperbarui.':'Survei dibuat. Unggah foto asli untuk memulai.');}
  if(e.target.id==='api-form'){e.preventDefault();const val=$('#api-url').value.trim();try{if(val){const url=new URL(val);if(!['http:','https:'].includes(url.protocol)||url.username||url.password)throw Error();}state.settings.apiUrl=val;await persist();render();toast('Endpoint disimpan. Kesiapan model diperiksa saat deteksi dijalankan.');}catch(err){$('#api-error').textContent='Gunakan URL HTTP/HTTPS yang valid tanpa kredensial dalam URL.';}}
});
$('#photo-input').addEventListener('change',async e=>{await uploadFiles(e.target.files);e.target.value='';});
$('#backup-input').addEventListener('change',async e=>{await restoreBackup(e.target.files[0]);e.target.value='';});
$('#detection-input').addEventListener('change',async e=>{const file=e.target.files[0],p=activePhoto();if(!file||!p)return;try{if(file.size>5*1024*1024)throw Error('JSON lebih dari 5 MB.');await addDetections(JSON.parse(await file.text()),p.id);}catch(err){toast('Impor deteksi gagal: '+err.message);}e.target.value='';});
document.addEventListener('keydown',e=>{if(e.target.matches('input,textarea,select'))return;const m=e.target.closest?.('[data-marker]');if(m&&(e.key==='Enter'||e.key===' ')){e.preventDefault();selectedId=m.dataset.marker;render();return;}if((e.ctrlKey||e.metaKey)&&e.key==='z'&&view==='overview'){e.preventDefault();$('[data-action="undo"]')?.click();}});
window.addEventListener('beforeunload',e=>{if(!sessionSaved){e.preventDefault();e.returnValue='';}});
init();
